        <div className="meta-item">
          <span className="meta-label">Role</span>
          <span className="meta-value">Admin</span>
        </div>

        <div className="meta-item">
          <span className="meta-label">Department</span>
          <span className="meta-value">Professional Learning</span>
        </div>

