      </Route>
      <Route element={<TeacherLayout />}>
        <Route path="/teacher" element={<TeacherDashboardPage />} />
        <Route path="/teacher/calendar" element={<TeacherCalendarPage />} />
      </Route>
    </Routes>
  );
}

export default App;
